    terme: "SOUS-ACTIVITÉ",
    domaine: "comptabilite",
    ues: [],
    definition: "Niveau d'activité se situant en deçà des capacités normales de production, ou de la production que l'entité peut raisonnablement attendre des moyens dont elle dispose.",
